"""Native Windows adapters. No shell command is generated by a language model."""

import os
import subprocess
from pathlib import Path
from urllib.parse import quote_plus, unquote, urlparse

from nisha.errors import NishaError
from nisha.process_lifetime import user_app_options


class DesktopAdapter:
    def __init__(self, apps=None):
        self.apps = apps or {}
        from nisha.app_catalog import AppCatalog

        self.catalog = AppCatalog()

    def app_path(self, name):
        name = name.casefold().strip()
        known = {
            "notepad": "notepad.exe",
            "word": "WINWORD.EXE",
            "microsoft word": "WINWORD.EXE",
            "outlook": "OUTLOOK.EXE",
            "vscode": "Code.exe",
            "vs code": "Code.exe",
            "visual studio code": "Code.exe",
            "calculator": "calc.exe",
            "paint": "mspaint.exe",
            "chrome": "chrome.exe",
            "google chrome": "chrome.exe",
            "browser": "msedge.exe",
            "edge": "msedge.exe",
            "microsoft edge": "msedge.exe",
        }
        if name in self.apps:
            path = Path(self.apps[name]).resolve()
            if path.is_file() and path.suffix.casefold() == ".exe":
                return str(path)
            raise NishaError("That app path is missing or isn't an executable. Check config apps.")
        exe = known.get(name)
        if exe in {"notepad.exe", "calc.exe", "mspaint.exe"}:
            return str(Path(os.environ.get("WINDIR", "C:/Windows")) / "System32" / exe)
        if exe is not None and os.name == "nt":
            import winreg

            for hive in [winreg.HKEY_CURRENT_USER, winreg.HKEY_LOCAL_MACHINE]:
                try:
                    with winreg.OpenKey(
                        hive, "SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\App Paths\\" + exe
                    ) as key:
                        path = winreg.QueryValue(key, None)
                        if Path(path).is_file():
                            return path
                except OSError:
                    continue
        return self.catalog.resolve(name)

    def open_app(self, name):
        path = self.app_path(name)
        if path is None:
            shortcut = self.catalog.resolve_shortcut(name)
            if shortcut is None:
                raise NishaError(
                    "I couldn't find that app or shortcut. Add its executable path to config apps."
                )
            os.startfile(str(shortcut), "open")
            return
        if path.startswith("shell:AppsFolder\\"):
            explorer = Path(os.environ.get("WINDIR", "C:/Windows")) / "explorer.exe"
            subprocess.Popen([str(explorer), path], shell=False, **user_app_options())
        else:
            subprocess.Popen([path], shell=False, **user_app_options())

    def open_path(self, path):
        path = Path(path)
        if not path.is_absolute() or not path.exists():
            raise NishaError("The saved local path is missing. Check it in Ctrl+D.")
        os.startfile(str(path), "open")

    def search_in_browser(self, name, query):
        if name not in {"chrome", "google chrome", "edge", "microsoft edge"}:
            raise NishaError("Choose Chrome or Edge for this browser search.")
        query = query.strip()
        if not 1 <= len(query) <= 200 or any(c in query for c in "\r\n\x00"):
            raise NishaError("Give me a shorter search phrase.")
        path = self.app_path(name)
        if not path or path.startswith("shell:AppsFolder\\"):
            raise NishaError(f"I couldn't find {name} on this PC.")
        url = "https://www.google.com/search?q=" + quote_plus(query)
        subprocess.Popen([path, url], shell=False, **user_app_options())

    def open_url_in_browser(self, name, url):
        if name not in {"chrome", "google chrome", "edge", "microsoft edge"}:
            raise NishaError("Choose Chrome or Edge for this website.")
        parsed = urlparse(url)
        if parsed.scheme not in {"http", "https"} or not parsed.hostname or parsed.username or parsed.password:
            raise NishaError("Give me a valid HTTP or HTTPS website address.")
        path = self.app_path(name)
        if not path or path.startswith("shell:AppsFolder\\"):
            raise NishaError(f"I couldn't find {name} on this PC.")
        subprocess.Popen([path, url], shell=False, **user_app_options())

    def search_youtube_channel(self, name, channel):
        if name != "chrome":
            raise NishaError("This channel playback command requires Chrome.")
        channel = channel.strip()
        if not 1 <= len(channel) <= 100 or any(c in channel for c in "\r\n\x00"):
            raise NishaError("Give me a shorter channel name.")
        path = self.app_path("chrome")
        if not path or path.startswith("shell:AppsFolder\\"):
            raise NishaError("I couldn't find Chrome on this PC.")
        url = (
            "https://www.youtube.com/results?search_query="
            + quote_plus(channel)
            + "&sp=EgIQAg%253D%253D"
        )
        subprocess.Popen([path, url], shell=False, **user_app_options())
        return url

    def open_folder(self, path):
        path = Path(path).resolve()
        if not path.is_dir():
            raise NishaError("That folder is unavailable.")
        explorer = Path(os.environ.get("WINDIR", "C:/Windows")) / "explorer.exe"
        subprocess.Popen([str(explorer), str(path)], shell=False, **user_app_options())

    def navigate_explorer(self, path, current):
        """Navigate one existing Explorer window; never silently create a new one."""
        this_pc = path == "this pc"
        destination = "shell:MyComputerFolder" if this_pc else Path(path).resolve()
        if not this_pc and not destination.is_dir():
            raise NishaError("That folder is unavailable.")
        if os.name != "nt":
            raise NishaError("Explorer navigation is available on Windows.")
        import pythoncom
        import win32com.client

        try:
            windows = win32com.client.Dispatch("Shell.Application").Windows()
            initialized_here = False
        except pythoncom.com_error:
            pythoncom.CoInitialize()
            initialized_here = True
            windows = win32com.client.Dispatch("Shell.Application").Windows()
        try:
            matches = []
            for window in windows:
                try:
                    location_url = str(window.LocationURL or "")
                    if current == "this pc":
                        found = (
                            "mycomputerfolder" in location_url.casefold()
                            or str(window.Document.Folder.Self.Path).casefold()
                            == "::{20d04fe0-3aea-1069-a2d8-08002b30309d}"
                        )
                    else:
                        current_path = Path(current).resolve()
                        found = (
                            location_url.casefold().startswith("file:")
                            and Path(unquote(urlparse(location_url).path).lstrip("/")).resolve()
                            == current_path
                        )
                    if found:
                        matches.append(window)
                except (OSError, AttributeError, ValueError):
                    continue
            if len(matches) != 1:
                raise NishaError(
                    "I couldn't identify one Explorer window at that location. Open the folder again and retry."
                )
            matches[0].Navigate2(str(destination))
        except NishaError:
            raise
        except Exception as exc:
            raise NishaError("Explorer didn't accept navigation in the same window.") from exc
        finally:
            if initialized_here:
                pythoncom.CoUninitialize()

    @staticmethod
    def desktop_directory():
        if os.name == "nt":
            try:
                from win32com.shell import shell, shellcon

                return Path(shell.SHGetFolderPath(0, shellcon.CSIDL_DESKTOPDIRECTORY, None, 0))
            except (ImportError, OSError):
                pass
        return Path.home() / "Desktop"

    def find_desktop_item(self, name, root=None):
        """Resolve one visible desktop item by exact name before any stem match."""
        root = Path(root or self.desktop_directory())
        name = name.strip().strip(".!?")
        if not 1 <= len(name) <= 120 or any(char in name for char in "/\\\x00\r\n"):
            raise NishaError("Name one desktop file or folder, without a path.")
        try:
            entries = list(root.iterdir())
        except OSError as exc:
            raise NishaError("The Desktop folder is unavailable.") from exc
        matches = [path for path in entries if path.name.casefold() == name.casefold()]
        if not matches:
            matches = [path for path in entries if path.stem.casefold() == name.casefold()]
        if len(matches) > 1:
            raise NishaError("Several desktop items match. Say the full name including its extension.")
        return matches[0] if matches else None

    def open_desktop_item(self, name):
        path = self.find_desktop_item(name)
        if path is None:
            raise NishaError(f"I couldn't find {name} on your Desktop.")
        if path.is_dir():
            self.open_folder(path)
            return path, "folder"
        self.open_file(path)
        return path, "file"

    def open_special(self, name):
        locations = {
            "recycle bin": "shell:RecycleBinFolder",
            "this pc": "shell:MyComputerFolder",
        }
        if name == "downloads":
            folder = Path.home() / "Downloads"
            self.open_folder(folder)
            return
        if name not in locations or os.name != "nt":
            raise NishaError("That Windows location is unavailable.")
        explorer = Path(os.environ.get("WINDIR", "C:/Windows")) / "explorer.exe"
        subprocess.Popen([str(explorer), locations[name]], shell=False, **user_app_options())

    def open_file(self, path):
        path = Path(path).resolve()
        if not path.is_file() or path.suffix.casefold() not in {
            ".txt",
            ".md",
            ".pdf",
            ".docx",
            ".pptx",
            ".xlsx",
            ".csv",
            ".jpg",
            ".jpeg",
            ".png",
            ".webp",
            ".gif",
            ".bmp",
        }:
            raise NishaError("That document is unavailable or unsupported.")
        options = user_app_options()
        if options:
            explorer = Path(os.environ.get("WINDIR", "C:/Windows")) / "explorer.exe"
            subprocess.Popen([str(explorer), str(path)], shell=False, **options)
        else:
            os.startfile(str(path), "open")

    def open_document(self, path, app="notepad"):
        path = Path(path).resolve()
        executable = self.app_path(app)
        if executable is None:
            raise NishaError(f"The file is saved, but {app} isn't available on this PC.")
        if app in {"word", "microsoft word"} and os.name == "nt":
            import pythoncom
            import win32com.client

            pythoncom.CoInitialize()
            word = document = None
            try:
                word = win32com.client.Dispatch("Word.Application")
                word.Visible = True
                document = word.Documents.Open(str(path), ReadOnly=False)
                if Path(document.FullName).resolve() != path:
                    raise NishaError("Word didn't confirm the requested document.")
            except Exception as exc:
                raise NishaError(
                    "The file is saved, but Word couldn't open it. Check Word for an open dialog."
                ) from exc
            finally:
                document = word = None
                pythoncom.CoUninitialize()
            return
        if executable.startswith("shell:AppsFolder\\"):
            raise NishaError(
                f"The file is saved. Configure {app}'s executable path to open documents in it."
            )
        process = subprocess.Popen([executable, str(path)], shell=False, **user_app_options())
        try:
            status = process.wait(timeout=0.2)
            if status:
                raise NishaError(f"The file is saved, but {app} exited with an error.")
        except subprocess.TimeoutExpired:
            pass
